def transform_grid(grid):
    rows = len(grid)
    cols = len(grid[0])

    color4 = set()
    color6 = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                color4.add((r, c))
            elif grid[r][c] == 6:
                color6.add((r, c))

    if not color4 or not color6:
        return grid

    min_4_r = min(c[0] for c in color4)
    min_6_r = min(c[0] for c in color6)

    result = [[0] * cols for _ in range(rows)]

    # Reflected rows first
    for r, c in color4:
        refl_r = min_6_r - (r - min_4_r)
        if 0 <= refl_r < rows:
            result[refl_r][c] = 4

    # Original rows second
    for r, c in color4:
        result[r][c] = 4

    return result

